public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {

    // Create a complete bipartite graph on the given target graph
    int numVertices = target.getNumVertices();
    int numEdges = (int)Math.ceil(numVertices / 2.0);
    List<GraphEdge> edges = new ArrayList<GraphEdge>();
    HashMap<Integer, GraphNode> nodeMap = new HashMap<Integer, GraphNode>();

    // Iterate over the target graph vertices and add them to the new graph
    for(V vertex : target.getVertices()) {
        int id = target.getVertexId(vertex);
        if(!nodeMap.containsKey(id)) {
            GraphNode loc0 = new GraphNode(id);
            nodeMap.put(id, loc0);
            numVertices++;
        }
    }

    // Iterate over the target graph edges and add them to the new graph
    for(GraphEdge edge : target.getEdges()) {
        int srcId = target.getVertexId(edge.getSrc());
        int dstId = target.getVertexId(edge.getDst());
        edges.add(edge);
        numEdges++;
        GraphNode srcNode = nodeMap.get(srcId);
        GraphNode dstNode = nodeMap.get(dstId);
        srcNode.addNeighbor(dstNode);
        dstNode.addNeighbor(srcNode);
    }

    // Return the complete bipartite graph
    Graph<V,E> completeGraph = new Graph<V,E>(numVertices, numEdges, edges, nodeMap);
    for(GraphEdge edge : completeGraph.getEdges()) {
        resultMap.put(edge.getId().toString(), edge);
    }
}

