Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the type is parameterized and if its argument can be resolved
    if (!(genericType instanceof ParameterizedType) || !(targetType instanceof Class<?>) || ((ParameterizedType) genericType).getRawType() != targetType) {
        return null;
    }

    // Get the arguments for the generic type
    Type[] genericArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Create an array to store the resolved arguments
    Class<?>[] resolvedArguments = new Class<?>[genericArguments.length];

    // Iterate over the arguments and resolve them
    for (int i = 0; i < genericArguments.length; i++) {
        resolvedArguments[i] = resolveRawArgument(((ParameterizedType) genericType).getActualTypeArguments()[i], targetType);
    }

    return resolvedArguments;
}

