    Class<?>[] resolvedArgs = new Class<?>[paramType.getActualTypeArguments().length];
    for (int i = 0; i < resolvedArgs.length; i++) {
        resolvedArgs[i] = resolveRawArgument(paramType.getActualTypeArguments()[i], targetType);
