    // Get the type variables for the target type
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();

    // Get the type arguments for the target type
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // Create a map of type variables to type arguments
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < typeParameters.length; i++) {
        typeVariableMap.put(typeParameters[i], typeArguments[i]);
    }

    // Resolve the type arguments for the target type
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        resolvedArguments[i] = resolveRawType(typeArguments[i], typeVariableMap);
    }

    return resolvedArguments;
}

