    List<String> inputFields = mappings.getIndex(tableName).getFieldNames();

    // Create a new Mappings object to store the output
    Mappings outputMappings = new Mappings();

    // Loop through each field in the input mappings and check if it is present in the output mappings
    for (String field : inputFields) {
        // If the field is not present in the output mappings, add it to the output
        if (!outputMappings.containsField(tableName, field)) {
            outputMappings.addField(tableName, field);
        }
    }

    // Return the output mappings
    return outputMappings;
}

