public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 11) {
        // If the dayStep is 11, we need to re-format the time bucket literal long value.
        // For example, in dayStep == 11, 20000105 re-formatted time bucket is 20000101
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);
        if (day > 15) {
            day = day - dayStep - 1;
        }
        return (long) (year * 10000 + month * 100 + day);
    }
    return timeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 1) {
        return timeBucket;
    }

    long newTimeBucket = 0;
    long dayBucket = timeBucket % 1000000000;
    long day = dayBucket % 100;
    day = day < dayStep ? 0 : day - dayStep;
    dayBucket = dayBucket - dayBucket % 100;
    dayBucket = dayBucket + day;

    int hour = (int)((timeBucket - dayBucket) / 1000000000);
    hour = hour < 100 ? 0 : hour - 100;
    long newDayBucket = dayBucket + hour * 1000000000;
    newTimeBucket = newDayBucket + timeBucket - dayBucket;

    return newTimeBucket;
}

