        int capacity = remaining;
        if (capacity > buffer.length - bufferPosition) {
            capacity = buffer.length - bufferPosition;
        }

        System.arraycopy(b, off, buffer, bufferPosition, capacity);
        bufferPosition += capacity;
        off += capacity;
