    List<String> pathComponents = Arrays.asList(path.split("/"));

    // Split the relative path into a list of components
    List<String> relativePathComponents = Arrays.asList(relativePath.split("/"));

    // Combine the path components with the relative path components
    List<String> combinedPathComponents = new ArrayList<>();
