public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshotFromLine(line);
            if (threadSnapshot != null) {
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (timeRange.contains(threadSnapshot.getTimestamp())) {
                        threadSnapshots.add(threadSnapshot);
                        break;
                    }
                }
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

        try (RandomAccessFile in = new RandomAccessFile(file, "r")) {
            // seek to the beginning of the file
            in.seek(0);

            // read the header
            HprofHeader hprofHeader = HprofHeader.read(in);

            // skip the header
            in.skipBytes(HprofBuffer.getUInt32(in.readInt()));

            // read the sub records
            HprofRecord subRecord = HprofRecord.read(in, hprofHeader.getHprofVersion());

            while (subRecord != null) {
                // process sub records
                switch (subRecord.getRecordType()) {
                    case STACK_FRAME:
                        // parse the stack frame
                        StackFrameRecord stackFrameRecord = (StackFrameRecord) subRecord;
                        // get the thread snapshot for this stack frame
                        ThreadSnapshot threadSnapshot = threadSnapshots.get(stackFrameRecord.getThreadId());
                        // add the stack frame to the thread snapshot
                        threadSnapshot.getStackTrace().addFrame(stackFrameRecord.getStackFrame());
                        break;
                    case STACK_TRACE:
                        // parse the stack trace
                        StackTraceRecord stackTraceRecord = (StackTraceRecord) subRecord;
                        // get the thread snapshot for this stack trace
                        threadSnapshot = threadSnapshots.get(stackTraceRecord.getThreadId());
                        // add the stack trace to the thread snapshot
                        threadSnapshot.getStackTrace().addStackTrace(stackTraceRecord.getStackTrace());
                        break;
                    case THREAD_INFO:
                        // parse the thread info
                        ThreadInfoRecord threadInfoRecord = (ThreadInfoRecord) subRecord;
                        // check if the thread info belongs to the time range
                        if (threadInfoRecord.getThreadId() >= timeRanges.get(0).getStart() && threadInfoRecord.getThreadId() <= timeRanges.get(0).getEnd()) {
                            // add the thread snapshot to the list
                            threadSnapshots.add(new ThreadSnapshot(threadInfoRecord.getThreadId(), threadInfoRecord.getThreadName(), threadInfoRecord.getThreadGroupName(), threadInfoRecord.getStackTraceSize()));
                        }
                        break;
                    default:
                        break;
                }

                // read the next sub record
                subRecord = HprofRecord.read(in, hprofHeader.getHprofVersion());
            }
        }

        return threadSnapshots;
    }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (FileInputStream fis = new FileInputStream(file); BufferedReader br = new BufferedReader(new InputStreamReader(fis, "UTF-8"))) {
        String line;
        while ((line = br.readLine()) != null) {
            // Skip empty lines and comment lines
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }
            // Parse the line
            String[] parts = line.split("\t");
            if (parts.length < 3) {
                throw new IOException("Invalid line: " + line);
            }
            // Get the timestamp, thread ID, and thread information
            long timestamp = Long.parseLong(parts[0]);
            int threadId = Integer.parseInt(parts[1]);
            String threadInfo = parts[2];
            // Check if the timestamp is within the specified time range
            boolean isInRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timestamp >= timeRange.getStart() && timestamp <= timeRange.getEnd()) {
                    isInRange = true;
                    break;
                }
            }
            if (isInRange) {
                // Add the thread snapshot to the list
                snapshots.add(new ThreadSnapshot(timestamp, threadId, threadInfo));
            }
        }
    }
    return snapshots;
}

