public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
Thread snapshot builder = new ThreadSnapshot.Builder();

// Parse the file content
try (FileReader reader = new FileReader(file)) {
String line = reader.readLine();
while (line != null) {
// Check if the line is a timestamp
if (line.startsWith("#")) {
String timestamp = line.substring(1).trim();
Date date = DATE_FORMAT.parse(timestamp);
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
if (date.getTime() >= timeRange.getStartTime().getTime() && date.getTime() <= timeRange.getEndTime().getTime()) {
// This line is in the time range, add it to the snapshot builder
snapshotBuilder.addEvent(createSnapshotEvent(line));
break;
}
}
}
else {
// This line is not a timestamp, skip it
}
}
}

// Build the snapshots
List<ThreadSnapshot> snapshots = new ArrayList<>();
long currentTime = 0; // current time in milliseconds
long lastSnapshotTime = 0; // the time of the last snapshot
ThreadSnapshot snapshot = null; // the current snapshot
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
snapshot = new ThreadSnapshot(timeRange);
snapshots.add(snapshot);
}

for (ThreadSnapshotEvent event : snapshotBuilder.getEvents()) {
long eventTime = event.getTimestamp().getTime();
if (eventTime > currentTime) {
if (lastSnapshotTime < eventTime) {
lastSnapshotTime = eventTime;
}
currentTime = Math.min(lastSnapshotTime + SNAPSHOT_DURATION, eventTime);
snapshot = snapshots.get((int)(currentTime - timeRange.getStartTime().getTime()) / SNAPSHOT_DURATION);
snapshot.addEvent(event);
}
}

// Return the snapshots
return snapshots;
}
